                ["RT.Metric.Hands"] = "Manos recibidas por el jugador en esa mesa.",
                ["RT.Note.Sample"] = "Las lecturas en tiempo real son mas utiles cuando cada mesa tiene suficientes manos; con muestras pequenas los colores pueden cambiar rapido.",
                ["RT.Note.HeroRow"] = "La fila del heroe permite comparar tu ritmo con el de los villanos activos en esa mesa.",
                ["RT.Note.File"] = "Si una mesa no actualiza, revisa que el archivo .txt sea el correcto y que la sala este escribiendo historial.",
                ["RT.Note.Refresh"] = "Los porcentajes se recalculan mientras entran nuevas manos al archivo.",
                ["HeroNote.WorstPosition"] = "La posicion mas costosa en la muestra es {0}: {1}, {2}.",
                ["HeroNote.BestPosition"] = "La posicion mas rentable es {0}: {1}.",
                ["HeroNote.WorstAction"] = "La accion con peor EV agregado es {0}: {1}.",
                ["HeroNote.TopCombo"] = "El combo mas jugado voluntariamente es {0}: {1} veces, {2} de la muestra.",
                ["HeroNote.HighFoldCBet"] = "Fold vs CBet alto: revisar defensas en flop, sobre todo en posicion y BB.",
                ["HeroNote.ShowdownReview"] = "Vas bastante al showdown y ganas poco: revisar calls de turn/river.",
                ["Common.Preflop"] = "PRE-FLOP"
            };

            AddRecentUiTranslations(es, "Espanol");

            var en = Merge(es, English());
            AddRecentUiTranslations(en, "English");

            var fr = Merge(en, French());
            AddRecentUiTranslations(fr, "Francais");

            var pt = Merge(en, Portuguese());
            AddRecentUiTranslations(pt, "Portugues");

            var de = Merge(en, German());
            AddRecentUiTranslations(de, "Deutsch");

            var ru = Merge(en, Russian());
            AddRecentUiTranslations(ru, "Русский");

            var ja = Merge(en, Japanese());
            AddRecentUiTranslations(ja, "日本語");

            return new(StringComparer.OrdinalIgnoreCase)
            {
                ["Espanol"] = es,
                ["English"] = en,
                ["Francais"] = fr,
                ["Portugues"] = pt,
                ["Deutsch"] = de,
                ["Русский"] = ru,
                ["日本語"] = ja
            };
        }

        private static Dictionary<string, string> Merge(Dictionary<string, string> baseDict, Dictionary<string, string> overrides)
        {
            var result = new Dictionary<string, string>(baseDict, StringComparer.OrdinalIgnoreCase);
            foreach (var item in overrides)
                result[item.Key] = item.Value;
            return result;
        }

